/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xt_diemcongxetuyen`
(
    `iddiemcong` int unsigned NOT NULL AUTO_INCREMENT,
    `ts_cccd`    varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    `manganh`    varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
    `matohop`    varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
    `phuongthuc` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
    `diemCC`     decimal(6, 2)                                                DEFAULT NULL,
    `diemUtxt`   decimal(6, 2)                                                DEFAULT NULL,
    `diemTong`   decimal(6, 2)                                                DEFAULT '0.00',
    `ghichu`     text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
    `dc_keys`    varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
    `status`     varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'active',
    PRIMARY KEY (`iddiemcong`),
    UNIQUE KEY `dc_keys_UNIQUE` (`dc_keys`),
    KEY          `idx_diemcong_cccd` (`ts_cccd`),
    KEY          `idx_diemcong_manganh` (`manganh`),
    KEY          `idx_diemcong_matohop` (`matohop`),
    CONSTRAINT `fk_diemcong_cccd` FOREIGN KEY (`ts_cccd`) REFERENCES `xt_thisinhxettuyen25` (`cccd`) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_diemcong_manganh` FOREIGN KEY (`manganh`) REFERENCES `xt_nganh` (`manganh`) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_diemcong_matohop` FOREIGN KEY (`matohop`) REFERENCES `xt_tohop_monthi` (`matohop`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=164 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
