--
-- Table structure for table `xt_nguyenvongxettuyen`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xt_nguyenvongxettuyen`
(
    `idnv`          int                                                          NOT NULL AUTO_INCREMENT,
    `nn_cccd`       varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
    `nv_manganh`    varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
    `nv_tt`         int                                                          NOT NULL,
    `diem_thxt`     decimal(10, 5)                                               DEFAULT NULL COMMENT 'đã cộng điểm môn chính',
    `diem_utqd`     decimal(10, 5)                                               DEFAULT NULL COMMENT 'Điểm UTQD theo tổ họp sẽ khác nhau.',
    `diem_cong`     decimal(6, 2)                                                DEFAULT NULL COMMENT 'Tong 3 mon chua tinh mon chinh + diem uu tien',
    `diem_xettuyen` decimal(10, 5)                                               DEFAULT NULL COMMENT 'đã cộng điểm ưu tiên',
    `nv_ketqua`     varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
    `nv_keys`       varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
    `tt_phuongthuc` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
    `tt_thm`        varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
    `status`        varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'active',
    PRIMARY KEY (`idnv`),
    UNIQUE KEY `nv_keys_UNIQUE` (`nv_keys`),
    KEY             `idx_nguyenvong_cccd` (`nn_cccd`),
    KEY             `idx_nguyenvong_manganh` (`nv_manganh`),
    KEY             `idx_nguyenvong_tt_thm` (`tt_thm`),
    CONSTRAINT `fk_nguyenvong_cccd` FOREIGN KEY (`nn_cccd`) REFERENCES `xt_thisinhxettuyen25` (`cccd`) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_nguyenvong_manganh` FOREIGN KEY (`nv_manganh`) REFERENCES `xt_nganh` (`manganh`) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT `fk_nguyenvong_tt_thm_matohop` FOREIGN KEY (`tt_thm`) REFERENCES `xt_tohop_monthi` (`matohop`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=516 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

