SET dc_keys = REPLACE(dc_keys, '008196064186', '018196064186')
WHERE dc_keys LIKE '%008196064186%';
UPDATE xt_nguyenvongxettuyen
SET nv_keys = REPLACE(nv_keys, '008196064186', '018196064186')
WHERE nv_keys LIKE '%008196064186%';

