-- USERS
SET @max_users = (SELECT MAX(user_id) FROM users);
SET @sql1 = CONCAT('ALTER TABLE users AUTO_INCREMENT = ', @max_users + 1);
PREPARE stmt1 FROM @sql1;
EXECUTE stmt1;

-- ROLES
