DELIMITER $$

CREATE TRIGGER auto_set_cccd
BEFORE INSERT ON users
FOR EACH ROW
BEGIN
    -- Nếu chưa có CCCD
    IF NEW.student_cccd IS NULL THEN
        -- Lấy CCCD từ bảng thí sinh theo username
        SET NEW.student_cccd = (
            SELECT cccd
            FROM xt_thisinhxettuyen25
            WHERE cccd = NEW.username
            LIMIT 1
        );
    END IF;
END$$

DELIMITER ;


